import{_ as d,S as l,n as r,p as u,a3 as o,q as a,J as t,C as s,A as n}from"./framework-3c337068.js";const c={},m={class:"warning custom-block"};function p(h,e){const i=l("RouterLink");return r(),u("div",null,[e[41]||(e[41]=o(`<h1 id="cloudlinux-isolates-beta" tabindex="-1"><a class="header-anchor" href="#cloudlinux-isolates-beta" aria-hidden="true">#</a> CloudLinux Isolates (BETA)</h1><p>CloudLinux Isolates isolates the individual websites of a single hosting account from one another. It has two layers, which are described in turn below:</p><ul><li><strong><a href="#cagefs-per-domain">CageFS per domain</a></strong> — <em>filesystem</em> isolation, so that a compromised website cannot reach another site&#39;s files.</li><li><strong><a href="#lve-per-domain">LVE per domain</a></strong> — <em>resource</em> isolation, so that one website&#39;s CPU, memory and I/O usage is limited and accounted for on its own.</li></ul><h2 id="cagefs-per-domain" tabindex="-1"><a class="header-anchor" href="#cagefs-per-domain" aria-hidden="true">#</a> CageFS Per Domain</h2><p>CloudLinux Isolates is a security feature that provides domain-level isolation within CageFS. It allows server administrators to isolate individual websites from each other, even when they belong to the same hosting account. This prevents cross-site attacks where a compromised website could access files or data from other websites on the same account.</p><h3 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h3><p>When CloudLinux Isolates is enabled for a domain:</p><ul><li>Each isolated website runs in its own isolated environment</li><li>PHP processes for isolated websites cannot access files from other websites</li><li>Crontab entries are automatically scoped to their respective document roots</li><li>Existing PHP processes are gracefully terminated and restarted in the isolated environment</li><li>Per-domain PHP Selector configuration is automatically set up (inheriting user-level settings)</li></ul><h3 id="prerequisites" tabindex="-1"><a class="header-anchor" href="#prerequisites" aria-hidden="true">#</a> Prerequisites</h3><h4 id="minimum-package-versions" tabindex="-1"><a class="header-anchor" href="#minimum-package-versions" aria-hidden="true">#</a> Minimum Package Versions</h4><table><thead><tr><th>Package</th><th>Minimum Version</th></tr></thead><tbody><tr><td>cagefs</td><td>7.6.29-1</td></tr><tr><td>lve-utils</td><td>6.6.31-1</td></tr><tr><td>lve (liblve)</td><td>2.2-1</td></tr><tr><td>lve-wrappers</td><td>0.7.13-1</td></tr><tr><td>alt-python27-cllib</td><td>3.4.33-1</td></tr></tbody></table><h4 id="compatible-web-servers" tabindex="-1"><a class="header-anchor" href="#compatible-web-servers" aria-hidden="true">#</a> Compatible Web Servers</h4><table><thead><tr><th>Web Server</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>Apache</td><td>✅ Supported</td><td>See <a href="#compatible-php-handlers">Compatible PHP Handlers</a> below for handler-specific requirements.</td></tr><tr><td>NGINX</td><td>🔜 Coming in future releases</td><td></td></tr><tr><td>LiteSpeed</td><td>✅ Supported (cPanel only)</td><td>Standalone LiteSpeed Web Server, on cPanel servers only. See <a href="#litespeed-requirements">LiteSpeed requirements</a> below.</td></tr></tbody></table><h5 id="litespeed-requirements" tabindex="-1"><a class="header-anchor" href="#litespeed-requirements" aria-hidden="true">#</a> LiteSpeed requirements</h5><p>CloudLinux Isolates is supported under <strong>standalone LiteSpeed Web Server</strong>, and for now <strong>on cPanel servers only</strong>.</p><p>In addition to the <a href="#minimum-package-versions">minimum package versions</a> listed above, LiteSpeed servers require:</p><table><thead><tr><th>Package</th><th>Minimum Version</th></tr></thead><tbody><tr><td>cagefs</td><td>7.6.47-1</td></tr><tr><td>lve-wrappers</td><td>0.7.16-1</td></tr><tr><td>lve (liblve)</td><td>2.2-8</td></tr><tr><td>ea-apache24-mod_hostinglimits</td><td>1.0-49</td></tr></tbody></table><p>To check the installed versions:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>rpm -q cagefs lve-wrappers lve ea-apache24-mod_hostinglimits
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h4 id="compatible-php-handlers" tabindex="-1"><a class="header-anchor" href="#compatible-php-handlers" aria-hidden="true">#</a> Compatible PHP Handlers</h4><p>The following table applies to <strong>Apache</strong>. For standalone LiteSpeed, see <a href="#litespeed-requirements">LiteSpeed requirements</a> above.</p><table><thead><tr><th>Handler</th><th>Status</th><th>Notes</th></tr></thead><tbody><tr><td>LSAPI</td><td>✅ Supported (Recommended)</td><td>Requires <code>lsapi_per_user Off</code> (the default). See <a href="#lsapi-per-user-restriction">LSAPI restriction</a> below.</td></tr><tr><td>CGI</td><td>✅ Supported</td><td></td></tr><tr><td>FPM</td><td>⚠️ Partially supported</td><td>See <a href="#compatible-php-versions">Compatible PHP Versions</a> for minimum package versions.</td></tr><tr><td>FCGI</td><td>🔜 Coming in future releases</td><td></td></tr></tbody></table><h5 id="lsapi-per-user-restriction" tabindex="-1"><a class="header-anchor" href="#lsapi-per-user-restriction" aria-hidden="true">#</a> LSAPI per-user restriction</h5>`,23)),a("p",null,[e[1]||(e[1]=t("The mod_lsapi directive ",-1)),s(i,{to:"/cloudlinuxos/cloudlinux_os_components/#lsapi-per-user"},{default:n(()=>e[0]||(e[0]=[a("code",null,"lsapi_per_user",-1)])),_:1,__:[0]}),e[2]||(e[2]=t(" controls how lsphp backend processes are spawned:",-1))]),e[42]||(e[42]=o(`<ul><li><strong><code>lsapi_per_user Off</code></strong> (default) — one lsphp master per virtual host. Each master receives the site&#39;s <code>DOCUMENT_ROOT</code> and enters the correct isolated environment. <strong>This is the only mode compatible with CloudLinux Isolates.</strong></li><li><strong><code>lsapi_per_user On</code></strong> — a single lsphp master serves all virtual hosts for a user. In this mode, mod_lsapi does not pass <code>DOCUMENT_ROOT</code> to the backend, so isolation cannot determine which site a request belongs to. <strong>This mode is incompatible with CloudLinux Isolates.</strong></li></ul><p>To check your current setting, run:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>grep -ri &#39;lsapi_per_user&#39; /etc/apache2/conf.d/ /etc/httpd/conf.d/ 2&gt;/dev/null
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>The directive is typically located in <code>/etc/apache2/conf.d/lsapi.conf</code> (cPanel) or <code>/etc/httpd/conf.d/lsapi.conf</code>. If the command returns no output, or all matches are commented out or show <code>Off</code>, your configuration is compatible (the default is <code>Off</code>). If any match shows <code>lsapi_per_user On</code> (uncommented), you must set it to <code>Off</code> before enabling CloudLinux Isolates.</p>`,4)),a("div",m,[e[6]||(e[6]=a("p",{class:"custom-block-title"},"Important",-1)),e[7]||(e[7]=a("p",null,[a("code",null,"lsapi_per_user On"),t(" is "),a("strong",null,"incompatible"),t(" with CloudLinux Isolates. In per-user mode, a single lsphp master process handles all virtual hosts for a user, making per-domain isolation architecturally impossible. Switch to "),a("code",null,"lsapi_per_user Off"),t(" (the default) before enabling isolation.")],-1)),a("p",null,[e[4]||(e[4]=t("For full details on this directive, see ",-1)),s(i,{to:"/cloudlinuxos/cloudlinux_os_components/#lsapi-per-user"},{default:n(()=>e[3]||(e[3]=[t("lsapi_per_user in mod_lsapi documentation",-1)])),_:1,__:[3]}),e[5]||(e[5]=t(".",-1))])]),e[43]||(e[43]=o('<h4 id="compatible-control-panels" tabindex="-1"><a class="header-anchor" href="#compatible-control-panels" aria-hidden="true">#</a> Compatible Control Panels</h4><table><thead><tr><th>Handler</th><th>Status</th></tr></thead><tbody><tr><td>cPanel</td><td>✅ Supported</td></tr><tr><td>Plesk</td><td>✅ Supported</td></tr><tr><td>DirectAdmin</td><td>✅ Supported</td></tr><tr><td>Integration Scripts*</td><td>✅ Supported</td></tr></tbody></table>',2)),a("p",null,[e[9]||(e[9]=t("*",-1)),s(i,{to:"/cloudlinuxos/control_panel_integration/#control-panel-api-integration"},{default:n(()=>e[8]||(e[8]=[t("Control Panel Integration",-1)])),_:1,__:[8]})]),e[44]||(e[44]=o(`<p>The table above applies to Apache. Under <a href="#litespeed-requirements">standalone LiteSpeed</a>, only cPanel is supported so far.</p><h4 id="compatible-php-versions" tabindex="-1"><a class="header-anchor" href="#compatible-php-versions" aria-hidden="true">#</a> Compatible PHP Versions</h4><p>CloudLinux Isolates provides partial FPM handler support for both ea-php (cPanel) and alt-php.</p><h5 id="ea-php-cpanel" tabindex="-1"><a class="header-anchor" href="#ea-php-cpanel" aria-hidden="true">#</a> ea-php (cPanel)</h5><table><thead><tr><th>Package</th><th>Minimum Version</th></tr></thead><tbody><tr><td>ea-php56-php</td><td>5.6.40-25.cloudlinux.3</td></tr><tr><td>ea-php70-php</td><td>7.0.33-29.cloudlinux.3</td></tr><tr><td>ea-php71-php</td><td>7.1.33-20.cloudlinux.3</td></tr><tr><td>ea-php72-php</td><td>7.2.34-12.cloudlinux.3</td></tr><tr><td>ea-php73-php</td><td>7.3.33-15.cloudlinux.3</td></tr><tr><td>ea-php74-php</td><td>7.4.33-16.cloudlinux.1</td></tr><tr><td>ea-php80-php</td><td>8.0.30-9.cloudlinux.1</td></tr><tr><td>ea-php81-php</td><td>8.1.33-2.cloudlinux.3</td></tr><tr><td>ea-php82-php</td><td>8.2.29-2.cloudlinux.3</td></tr><tr><td>ea-php83-php</td><td>8.3.30-1.cloudlinux.1</td></tr><tr><td>ea-php84-php</td><td>8.4.17-1.cloudlinux.2</td></tr><tr><td>ea-php85-php</td><td>8.5.2-1.cloudlinux.1</td></tr></tbody></table><h5 id="alt-php" tabindex="-1"><a class="header-anchor" href="#alt-php" aria-hidden="true">#</a> alt-php</h5><table><thead><tr><th>Package</th><th>Minimum Version</th></tr></thead><tbody><tr><td>alt-php53-php-fpm</td><td>5.3.29-189</td></tr><tr><td>alt-php54-php-fpm</td><td>5.4.45-172</td></tr><tr><td>alt-php55-php-fpm</td><td>5.5.38-152</td></tr><tr><td>alt-php56-php-fpm</td><td>5.6.40-116</td></tr><tr><td>alt-php70-php-fpm</td><td>7.0.33-117</td></tr><tr><td>alt-php71-php-fpm</td><td>7.1.33-83</td></tr><tr><td>alt-php72-php-fpm</td><td>7.2.34-65</td></tr><tr><td>alt-php73-php-fpm</td><td>7.3.33-51</td></tr><tr><td>alt-php74-php-fpm</td><td>7.4.33-48</td></tr><tr><td>alt-php80-php-fpm</td><td>8.0.30-36</td></tr><tr><td>alt-php81-php-fpm</td><td>8.1.34-5</td></tr><tr><td>alt-php82-php-fpm</td><td>8.2.30-5</td></tr><tr><td>alt-php83-php-fpm</td><td>8.3.30-5</td></tr><tr><td>alt-php84-php-fpm</td><td>8.4.18-2</td></tr><tr><td>alt-php85-php-fpm</td><td>8.5.3-3</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Note</p><p>alt-php53, alt-php54, and alt-php55 are supported on CL7/CL8/CL9 only. CL10 support starts from alt-php56.</p></div><hr><h3 id="quick-start" tabindex="-1"><a class="header-anchor" href="#quick-start" aria-hidden="true">#</a> Quick Start</h3><p>Follow these steps to enable CloudLinux Isolates for a domain:</p><p><strong>1. Allow the feature server-wide (administrator only, one-time setup):</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-allow-all
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>2. Enable isolation for a specific domain:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-enable &lt;example.com&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>3. Verify isolation is active:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-list
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>To disable isolation for a domain:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-disable &lt;example.com&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><hr><h3 id="command-reference" tabindex="-1"><a class="header-anchor" href="#command-reference" aria-hidden="true">#</a> Command Reference</h3><h4 id="server-wide-management" tabindex="-1"><a class="header-anchor" href="#server-wide-management" aria-hidden="true">#</a> Server-Wide Management</h4><h5 id="allow-cloudlinux-isolates-for-all-users" tabindex="-1"><a class="header-anchor" href="#allow-cloudlinux-isolates-for-all-users" aria-hidden="true">#</a> Allow CloudLinux Isolates for All Users</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-allow-all
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Enables the CloudLinux Isolates feature server-wide in &quot;Allow All&quot; mode. All users are allowed to use CloudLinux Isolates by default (individual users can be denied with <code>--site-isolation-deny</code>).</p><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-allow-all
CloudLinux Isolates was allowed for all users.
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Notes:</strong></p><ul><li>Creates the feature flag at <code>/opt/cloudlinux/flags/enabled-flags.d/website-isolation.flag</code></li><li>Sets up the per-user denied directory at <code>/etc/cagefs/site-isolation.users.denied</code></li><li>Triggers a CageFS remount to apply necessary mount configurations</li><li>Registers the <code>isolatectl</code> proxyexec command for user-level management</li><li>Must be run with root privileges</li></ul><hr><h5 id="deny-cloudlinux-isolates-for-all-users" tabindex="-1"><a class="header-anchor" href="#deny-cloudlinux-isolates-for-all-users" aria-hidden="true">#</a> Deny CloudLinux Isolates for All Users</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-deny-all
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Disables the CloudLinux Isolates feature server-wide and switches to &quot;Deny All&quot; mode. Removes all domain isolation configurations for all users.</p><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-deny-all
CloudLinux Isolates was denied for all users.
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Warning:</strong> This command will:</p><ul><li>Disable isolation for all currently isolated domains</li><li>Remove all per-user isolation configurations</li><li>Terminate and restart affected PHP processes</li><li>Clean up token directories and overlay storage</li><li>Switch to &quot;Deny All&quot; mode</li></ul><hr><h4 id="per-user-management" tabindex="-1"><a class="header-anchor" href="#per-user-management" aria-hidden="true">#</a> Per-User Management</h4><p>CloudLinux Isolates uses a two-mode user model to control which users can use the feature:</p><ul><li><strong>Allow All mode</strong> (<code>allow_all</code>): All users are allowed by default. Individual users can be denied (added as exceptions).</li><li><strong>Deny All mode</strong> (<code>deny_all</code>): No users are allowed by default. Individual users can be allowed (added as exceptions).</li></ul><h5 id="allow-cloudlinux-isolates-for-a-specific-user" tabindex="-1"><a class="header-anchor" href="#allow-cloudlinux-isolates-for-a-specific-user" aria-hidden="true">#</a> Allow CloudLinux Isolates for a Specific User</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-allow &lt;username&gt; [&lt;username2&gt; ...]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Allows CloudLinux Isolates for one or more specific users.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;username&gt;</code></td><td>Username(s) to allow CloudLinux Isolates for</td></tr></tbody></table><p><strong>Behavior depends on current mode:</strong></p><ul><li><strong>Allow All mode</strong>: Removes the user from the denied list (undoes a previous <code>--site-isolation-deny</code>)</li><li><strong>Deny All mode</strong>: Adds the user to the allowed list</li><li><strong>Not initialized</strong>: Sets up infrastructure in Deny All mode with the user as the first allowed user</li></ul><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-allow john
CloudLinux Isolates was allowed for user(s): john

# cagefsctl --site-isolation-allow john jane
CloudLinux Isolates was allowed for user(s): john, jane
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h5 id="deny-cloudlinux-isolates-for-a-specific-user" tabindex="-1"><a class="header-anchor" href="#deny-cloudlinux-isolates-for-a-specific-user" aria-hidden="true">#</a> Deny CloudLinux Isolates for a Specific User</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-deny &lt;username&gt; [&lt;username2&gt; ...]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Denies CloudLinux Isolates for one or more specific users and disables all their domain isolation.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;username&gt;</code></td><td>Username(s) to deny CloudLinux Isolates for</td></tr></tbody></table><p><strong>Behavior depends on current mode:</strong></p><ul><li><strong>Allow All mode</strong>: Adds the user to the denied list</li><li><strong>Deny All mode</strong>: Removes the user from the allowed list (undoes a previous <code>--site-isolation-allow</code>)</li></ul><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-deny john
CloudLinux Isolates was denied for user(s): john
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Notes:</strong></p><ul><li>Also cleans up all existing domain isolation for the denied user(s)</li><li>CloudLinux Isolates must be enabled server-wide first</li></ul><hr><h5 id="toggle-user-mode" tabindex="-1"><a class="header-anchor" href="#toggle-user-mode" aria-hidden="true">#</a> Toggle User Mode</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-toggle-mode
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Toggles the isolation user mode between &quot;Allow All&quot; and &quot;Deny All&quot; without modifying any per-user exception lists.</p><p><strong>Mode transitions:</strong></p><ul><li><code>allow_all</code> → <code>deny_all</code></li><li><code>deny_all</code> → <code>allow_all</code></li><li>Not initialized → <code>allow_all</code></li></ul><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-toggle-mode
CloudLinux Isolates user mode toggled to &#39;deny_all&#39;.
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Notes:</strong></p><ul><li>Only flips the mode indicator directories</li><li>Does <strong>not</strong> clean up existing user isolation</li><li>Does <strong>not</strong> alter the per-user exception lists</li><li>Useful for quickly switching the default behavior without losing per-user configuration</li></ul><hr><h4 id="domain-level-management" tabindex="-1"><a class="header-anchor" href="#domain-level-management" aria-hidden="true">#</a> Domain-Level Management</h4><h5 id="enable-isolation-for-a-domain" tabindex="-1"><a class="header-anchor" href="#enable-isolation-for-a-domain" aria-hidden="true">#</a> Enable Isolation for a Domain</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-enable &lt;domain&gt; [&lt;domain2&gt; ...]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Enables CloudLinux Isolates for one or more specified domains.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;domain&gt;</code></td><td>Domain name to isolate (e.g., <code>example.com</code>)</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-enable example.com
CloudLinux Isolates was enabled for domain(s),
example.com

# cagefsctl --site-isolation-enable site1.com site2.com
CloudLinux Isolates was enabled for domain(s),
site1.com,site2.com
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Requirements:</strong></p><ul><li>CloudLinux Isolates must be allowed server-wide first</li><li>CloudLinux Isolates must be allowed for the domain&#39;s user</li><li>The domain must exist and be associated with a valid user account</li><li>Must be run with root privileges</li></ul><p><strong>What happens when isolation is enabled:</strong></p><ol><li>A unique website token directory is created</li><li>Overlay storage directory is configured for the website</li><li>User configuration is updated with the isolated domain</li><li>Per-domain PHP Selector configuration is set up (inheriting from user&#39;s PHP settings)</li><li>If this is the first isolated website for the user, CageFS is remounted</li><li>Existing PHP processes for the domain are terminated and restarted in isolation</li><li>Document root monitoring service is started</li></ol><hr><h5 id="disable-isolation-for-a-domain" tabindex="-1"><a class="header-anchor" href="#disable-isolation-for-a-domain" aria-hidden="true">#</a> Disable Isolation for a Domain</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-disable &lt;domain&gt; [&lt;domain2&gt; ...]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Disables CloudLinux Isolates for one or more specified domains.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;domain&gt;</code></td><td>Domain name to remove from isolation</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-disable example.com
CloudLinux Isolates was disabled for domain(s),
example.com
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Requirements:</strong></p><ul><li>Must be run with root privileges</li></ul><p><strong>What happens when isolation is disabled:</strong></p><ol><li>Domain is removed from the user&#39;s isolation configuration</li><li>Mount configuration is regenerated</li><li>PHP processes for the domain are restarted outside of isolation</li><li>Token directories are cleaned up</li><li>If no users have any isolated domains left, the monitoring service is stopped</li></ol><hr><h4 id="monitoring-and-management" tabindex="-1"><a class="header-anchor" href="#monitoring-and-management" aria-hidden="true">#</a> Monitoring and Management</h4><h5 id="list-isolated-domains" tabindex="-1"><a class="header-anchor" href="#list-isolated-domains" aria-hidden="true">#</a> List Isolated Domains</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-list [&lt;username&gt; ...]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Lists all users and domains that have CloudLinux Isolates enabled.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;username&gt;</code></td><td>(Optional) Filter results by specific user(s)</td></tr></tbody></table><p><strong>Example - List all isolated domains:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-list

Domains with enabled CloudLinux Isolates for user john:
example.com
mysite.org

Domains with enabled CloudLinux Isolates for user jane:
shop.example.com
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Example - List isolated domains for specific user:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-list john

Domains with enabled CloudLinux Isolates for user john:
example.com
mysite.org
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Output when no domains are isolated:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-list
No users with enabled CloudLinux Isolates
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><hr><h5 id="regenerate-isolation-configuration" tabindex="-1"><a class="header-anchor" href="#regenerate-isolation-configuration" aria-hidden="true">#</a> Regenerate Isolation Configuration</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefsctl --site-isolation-regenerate &lt;username&gt; [&lt;username2&gt; ...]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Regenerates the CloudLinux Isolates configuration for specified users. Use this command after manual configuration changes or when troubleshooting isolation issues.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;username&gt;</code></td><td>Username(s) to regenerate configuration for</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># cagefsctl --site-isolation-regenerate john jane
Regenerated configuration CloudLinux Isolates for users:
john
jane
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>When to use:</strong></p><ul><li>After domain document root changes</li><li>After domain renames or migrations</li><li>When isolation configuration appears out of sync</li><li>As part of troubleshooting steps recommended by support</li></ul><hr><h3 id="user-level-management-isolatectl" tabindex="-1"><a class="header-anchor" href="#user-level-management-isolatectl" aria-hidden="true">#</a> User-Level Management (<code>isolatectl</code>)</h3><p>End users can manage CloudLinux Isolates and per-domain resource limits for their own domains using the <code>isolatectl</code> utility. All output is JSON.</p><p><code>isolatectl</code> must be run as a regular (non-root) user. It automatically identifies the calling user — no <code>--username</code> or <code>--lve-id</code> flags are needed.</p><div class="tip custom-block"><p class="custom-block-title">Note</p><p>User-level management requires that CloudLinux Isolates is allowed server-wide <strong>and</strong> allowed for the specific user by the server administrator.</p></div><h4 id="site-isolation" tabindex="-1"><a class="header-anchor" href="#site-isolation" aria-hidden="true">#</a> Site Isolation</h4><h5 id="enable-isolation-for-a-domain-user-level" tabindex="-1"><a class="header-anchor" href="#enable-isolation-for-a-domain-user-level" aria-hidden="true">#</a> Enable Isolation for a Domain (User-Level)</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>isolatectl site-isolation enable --domain &lt;domain&gt;[,&lt;domain2&gt;,...]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Enables CloudLinux Isolates for one or more domains owned by the calling user.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>--domain</code></td><td>Comma-separated domain name(s) to enable isolation for</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>$ isolatectl site-isolation enable --domain example.com
{&quot;result&quot;: &quot;success&quot;, &quot;enabled_sites&quot;: [&quot;example.com&quot;]}

$ isolatectl site-isolation enable --domain site1.com,site2.com
{&quot;result&quot;: &quot;success&quot;, &quot;enabled_sites&quot;: [&quot;site1.com&quot;, &quot;site2.com&quot;]}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Notes:</strong></p><ul><li>The user can only manage domains they own</li><li>CloudLinux Isolates must be allowed for the user by the server administrator</li></ul><hr><h5 id="disable-isolation-for-a-domain-user-level" tabindex="-1"><a class="header-anchor" href="#disable-isolation-for-a-domain-user-level" aria-hidden="true">#</a> Disable Isolation for a Domain (User-Level)</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>isolatectl site-isolation disable --domain &lt;domain&gt;[,&lt;domain2&gt;,...]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Disables CloudLinux Isolates for one or more domains owned by the calling user.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>--domain</code></td><td>Comma-separated domain name(s) to disable isolation for</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>$ isolatectl site-isolation disable --domain example.com
{&quot;result&quot;: &quot;success&quot;, &quot;enabled_sites&quot;: []}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><hr><h5 id="list-isolated-domains-user-level" tabindex="-1"><a class="header-anchor" href="#list-isolated-domains-user-level" aria-hidden="true">#</a> List Isolated Domains (User-Level)</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>isolatectl site-isolation list
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Lists all domains with CloudLinux Isolates enabled for the calling user.</p><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>$ isolatectl site-isolation list
{&quot;result&quot;: &quot;success&quot;, &quot;enabled_sites&quot;: [&quot;example.com&quot;, &quot;mysite.org&quot;]}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><hr><h4 id="per-domain-resource-limits" tabindex="-1"><a class="header-anchor" href="#per-domain-resource-limits" aria-hidden="true">#</a> Per-Domain Resource Limits</h4><p>Per-domain resource limits allow end users to set and apply individual CPU, memory, I/O, and process limits for each isolated domain. Domain limits require site isolation to be enabled first.</p><h5 id="list-domain-limits" tabindex="-1"><a class="header-anchor" href="#list-domain-limits" aria-hidden="true">#</a> List Domain Limits</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>isolatectl limits list [--domain &lt;domain&gt;]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Shows the configured limits for all domains or a specific domain.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>--domain</code></td><td>(Optional) Show limits for a specific domain only</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>$ isolatectl limits list
{
  &quot;result&quot;: &quot;success&quot;,
  &quot;domains&quot;: [
    {
      &quot;name&quot;: &quot;example.com&quot;,
      &quot;lve_id&quot;: 1000,
      &quot;limits&quot;: {&quot;cpu&quot;: 2500, &quot;pmem&quot;: 1048576}
    }
  ]
}

$ isolatectl limits list --domain example.com
{
  &quot;result&quot;: &quot;success&quot;,
  &quot;domains&quot;: [
    {
      &quot;name&quot;: &quot;example.com&quot;,
      &quot;lve_id&quot;: 1000,
      &quot;limits&quot;: {&quot;cpu&quot;: 2500, &quot;pmem&quot;: 1048576}
    }
  ]
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h5 id="set-domain-limits" tabindex="-1"><a class="header-anchor" href="#set-domain-limits" aria-hidden="true">#</a> Set Domain Limits</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>isolatectl limits set --domain &lt;domain&gt; [--cpu VAL] [--pmem VAL] [--io VAL] [--nproc VAL] [--iops VAL] [--ep VAL] [--vmem VAL]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Stores per-domain limits in the user&#39;s config and applies them to the kernel.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>--domain</code></td><td>Domain name (required)</td></tr><tr><td><code>--cpu</code></td><td>CPU limit (hundredths of percent, e.g. 2500 = 25%)</td></tr><tr><td><code>--pmem</code></td><td>Physical memory limit (bytes)</td></tr><tr><td><code>--io</code></td><td>I/O limit (KB/s)</td></tr><tr><td><code>--nproc</code></td><td>Max processes</td></tr><tr><td><code>--iops</code></td><td>I/O operations per second</td></tr><tr><td><code>--ep</code></td><td>Max entry processes (concurrent connections)</td></tr><tr><td><code>--vmem</code></td><td>Virtual memory limit (bytes)</td></tr></tbody></table><p>At least one limit parameter is required.</p><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>$ isolatectl limits set --domain example.com --cpu 5000 --pmem 268435456 --io 2048 --nproc 30 --iops 500 --ep 20 --vmem 536870912
{
  &quot;result&quot;: &quot;success&quot;,
  &quot;domain&quot;: &quot;example.com&quot;,
  &quot;limits&quot;: {
    &quot;cpu&quot;: 5000,
    &quot;pmem&quot;: 268435456,
    &quot;io&quot;: 2048,
    &quot;nproc&quot;: 30,
    &quot;iops&quot;: 500,
    &quot;ep&quot;: 20,
    &quot;vmem&quot;: 536870912
  }
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>This sets: CPU 50%, 256 MB PMEM, 2048 KB/s IO, 30 procs, 500 IOPS, 20 entry procs, 512 MB VMEM.</p><hr><h5 id="apply-domain-limits" tabindex="-1"><a class="header-anchor" href="#apply-domain-limits" aria-hidden="true">#</a> Apply Domain Limits</h5><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>isolatectl limits apply --domain &lt;domain&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Pushes the stored limits for a domain from the config file to the kernel. Use after manually editing the config or to re-apply limits after a restart.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>--domain</code></td><td>Domain name</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>$ isolatectl limits apply --domain example.com
{
  &quot;result&quot;: &quot;success&quot;,
  &quot;domain&quot;: &quot;example.com&quot;,
  &quot;limits&quot;: {&quot;cpu&quot;: 5000, &quot;pmem&quot;: 268435456}
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="per-domain-statistics" tabindex="-1"><a class="header-anchor" href="#per-domain-statistics" aria-hidden="true">#</a> Per-Domain Statistics</h4><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>isolatectl stats [--domain &lt;domain&gt;] [--period &lt;period&gt;]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Shows resource usage for the calling account&#39;s isolated domains. Like the rest of <span class="notranslate"><code>isolatectl</code></span>, it is run by the account owner rather than by root, identifies the caller automatically, and returns JSON.</p><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>--domain</code></td><td>(Optional) Report a single domain only</td></tr><tr><td><code>--period</code></td><td>(Optional) Time window to report over; default <code>10m</code></td></tr></tbody></table><p>The period grammar is <span class="notranslate"><code>lveinfo</code></span>&#39;s: <span class="notranslate"><code>s</code></span>, <span class="notranslate"><code>m</code></span>, <span class="notranslate"><code>h</code></span>, <span class="notranslate"><code>d</code></span>, plus <span class="notranslate"><code>today</code></span>. <strong><span class="notranslate"><code>1m</code></span> is one minute, not one month</strong> — a month is <span class="notranslate"><code>30d</code></span>.</p><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>$ isolatectl stats --domain example.com --period 1d
{
  &quot;result&quot;: &quot;success&quot;,
  &quot;scope&quot;: {
    &quot;owner_uid&quot;: 1000,
    &quot;period&quot;: &quot;1d&quot;,
    &quot;note&quot;: &quot;only domains active during the window are recorded&quot;
  },
  &quot;domains&quot;: [
    {
      &quot;name&quot;: &quot;example.com&quot;,
      &quot;lve_id&quot;: 60057,
      &quot;owner_uid&quot;: 1000,
      &quot;usage&quot;:  {&quot;cpu&quot;: 120, &quot;ep&quot;: 2, &quot;vmem&quot;: 0, &quot;pmem&quot;: 4096, &quot;nproc&quot;: 5, &quot;io&quot;: 0, &quot;iops&quot;: 0},
      &quot;peak&quot;:   {&quot;cpu&quot;: 900, &quot;ep&quot;: 5, &quot;vmem&quot;: 0, &quot;pmem&quot;: 9012, &quot;nproc&quot;: 9, &quot;io&quot;: 0, &quot;iops&quot;: 0},
      &quot;limits&quot;: {&quot;cpu&quot;: 5000, &quot;ep&quot;: 20, &quot;vmem&quot;: 0, &quot;pmem&quot;: 65536, &quot;nproc&quot;: 30, &quot;io&quot;: 2048, &quot;iops&quot;: 500},
      &quot;faults&quot;: {&quot;cpu&quot;: 0, &quot;ep&quot;: 3, &quot;vmem&quot;: 0, &quot;pmem&quot;: 0, &quot;nproc&quot;: 0, &quot;io&quot;: 0, &quot;iops&quot;: 0}
    }
  ]
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><span class="notranslate"><code>usage</code></span> is the average over the window, <span class="notranslate"><code>peak</code></span> the highest sample in it, and <span class="notranslate"><code>limits</code></span> the caps in force.</p><div class="warning custom-block"><p class="custom-block-title">An idle website is absent, not zero</p><p>Only domains that were active during the period are recorded at all, so a quiet website does not appear in <span class="notranslate"><code>domains</code></span> rather than appearing with zeroes. An empty <span class="notranslate"><code>domains</code></span> list is an ordinary answer, not an error — the <span class="notranslate"><code>scope</code></span> object is always returned so that &quot;quiet&quot; can be told apart from &quot;no such account&quot;.</p></div><hr><h3 id="executing-commands-in-an-isolated-site-context" tabindex="-1"><a class="header-anchor" href="#executing-commands-in-an-isolated-site-context" aria-hidden="true">#</a> Executing Commands in an Isolated Site Context</h3><p>The <code>cagefs_enter_site</code> utility allows executing a command inside CageFS in the context of a specific isolated website. This can be useful for debugging or running site-specific operations.</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>cagefs_enter_site &lt;site&gt; &lt;command&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>Parameters:</strong></p><table><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;site&gt;</code></td><td>Document root path or domain name</td></tr><tr><td><code>&lt;command&gt;</code></td><td>Command to execute inside the site&#39;s CageFS</td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>$ cagefs_enter_site example.com /bin/ls /home/user/public_html
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>Notes:</strong></p><ul><li>This command cannot be run as root</li><li>The site parameter can be either a document root path or a domain name</li></ul><hr><h3 id="per-domain-php-selector" tabindex="-1"><a class="header-anchor" href="#per-domain-php-selector" aria-hidden="true">#</a> Per-Domain PHP Selector</h3><p>When CloudLinux Isolates is enabled for a domain, per-domain PHP Selector configuration is automatically set up. This allows each isolated website to have its own PHP version and module configuration, independent of other websites on the same account.</p><p><strong>Key behaviors:</strong></p><ul><li>When isolation is first enabled for a domain, the domain <strong>inherits</strong> the user&#39;s current PHP version and module settings</li><li>Each isolated domain stores its PHP selector configuration separately</li></ul><h4 id="setting-php-version-for-an-isolated-domain" tabindex="-1"><a class="header-anchor" href="#setting-php-version-for-an-isolated-domain" aria-hidden="true">#</a> Setting PHP Version for an Isolated Domain</h4><p>Use <code>selectorctl</code> with the <code>--domain</code> option to set the PHP version for a specific isolated domain:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>selectorctl --set-user-current=&lt;version&gt; --domain &lt;domain&gt; [--user &lt;username&gt;]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>The <code>--user</code> option is only required when running as root. When a regular user runs <code>selectorctl</code>, it operates on their own account automatically.</p></div><p><strong>Example</strong> — set PHP 8.2 for <code>example.com</code>:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># As root:
selectorctl --set-user-current=8.2 --domain example.com --user john

# As the user:
selectorctl --set-user-current=8.2 --domain example.com
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="enabling-disabling-extensions-for-an-isolated-domain" tabindex="-1"><a class="header-anchor" href="#enabling-disabling-extensions-for-an-isolated-domain" aria-hidden="true">#</a> Enabling/Disabling Extensions for an Isolated Domain</h4><p>Use <code>selectorctl</code> with the <code>--domain</code> option to manage extensions per domain:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># Enable extensions
selectorctl --enable-user-extensions=&lt;ext1&gt;,&lt;ext2&gt; --version &lt;version&gt; --domain &lt;domain&gt; [--user &lt;username&gt;]

# Disable extensions
selectorctl --disable-user-extensions=&lt;ext1&gt;,&lt;ext2&gt; --version &lt;version&gt; --domain &lt;domain&gt; [--user &lt;username&gt;]

# List enabled extensions
selectorctl --list-user-extensions --version &lt;version&gt; --domain &lt;domain&gt; [--user &lt;username&gt;]
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p>The <code>--user</code> option is only required when running as root.</p></div><h3 id="troubleshooting" tabindex="-1"><a class="header-anchor" href="#troubleshooting" aria-hidden="true">#</a> Troubleshooting</h3><h4 id="common-issues" tabindex="-1"><a class="header-anchor" href="#common-issues" aria-hidden="true">#</a> Common Issues</h4><p><strong>&quot;CloudLinux Isolates is not enabled&quot;</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># Solution: Allow server-wide first
cagefsctl --site-isolation-allow-all
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>&quot;CloudLinux Isolates feature is not available on this platform&quot;</strong></p><p>The server does not have the required packages installed. Ensure all <a href="#minimum-package-versions">prerequisite packages</a> are installed and up to date.</p><p><strong>&quot;CloudLinux Isolates is not allowed for user &lt;username&gt;&quot;</strong></p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># Solution: Allow for the specific user
cagefsctl --site-isolation-allow &lt;username&gt;
# Or allow for all users
cagefsctl --site-isolation-allow-all
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>&quot;Please specify existing domain name and try again&quot;</strong></p><ul><li>Verify the domain exists in the control panel</li><li>Check that the domain is associated with a valid user account</li></ul><hr><h3 id="integration-with-control-panels" tabindex="-1"><a class="header-anchor" href="#integration-with-control-panels" aria-hidden="true">#</a> Integration with Control Panels</h3><p>CloudLinux Isolates integrates automatically with supported control panels. When domains are:</p><ul><li><strong>Created</strong>: No automatic action (isolation must be explicitly enabled)</li><li><strong>Renamed</strong>: Isolation configuration is automatically updated</li><li><strong>Deleted</strong>: Isolation configuration is automatically cleaned up</li><li><strong>Document root changed</strong>: Configuration is regenerated via hooks</li></ul><hr><h2 id="lve-per-domain" tabindex="-1"><a class="header-anchor" href="#lve-per-domain" aria-hidden="true">#</a> LVE Per Domain</h2><p>CloudLinux Isolates also allows resource limits — CPU, memory, I/O, processes and entry processes — to be applied to an <em>individual website</em> rather than to the hosting account as a whole. A single busy or misbehaving site is then throttled on its own, without consuming the resources its sibling sites on the same account depend on.</p><div class="warning custom-block"><p class="custom-block-title">BETA</p><p>Per-domain LVE limits are a BETA feature, supported on CloudLinux OS 8 and 9.</p></div><h3 id="how-it-relates-to-cagefs-per-domain" tabindex="-1"><a class="header-anchor" href="#how-it-relates-to-cagefs-per-domain" aria-hidden="true">#</a> How it relates to CageFS per domain</h3><p>The two halves of CloudLinux Isolates are separate layers and can be reasoned about separately:</p><table><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><a href="#cagefs-per-domain">CageFS per domain</a></td><td><em>Filesystem</em> isolation — a compromised website cannot read another site&#39;s files. Always available where CageFS is.</td></tr><tr><td>LVE per domain</td><td><em>Resource</em> isolation — a website has its own CPU, memory, I/O and process limits. Requires CloudLinux OS 8 or 9 and the package versions listed under <a href="#per-domain-prerequisites">Per-Domain Prerequisites</a>.</td></tr></tbody></table><p>In practice you do not enable them separately. The <span class="notranslate"><code>cagefsctl --site-isolation-*</code></span> commands documented above drive both: each one invokes the matching <span class="notranslate"><code>lvectl</code></span> per-domain command for you when the prerequisites are met, and silently skips that step when they are not. So on a server that does not support per-domain LVEs, website isolation still works — you get the filesystem separation without the resource limits, rather than an error.</p><h3 id="per-domain-prerequisites" tabindex="-1"><a class="header-anchor" href="#per-domain-prerequisites" aria-hidden="true">#</a> Per-Domain Prerequisites</h3><p>Per-domain LVE limits are supported on CloudLinux OS 8 and 9. CloudLinux OS 7 predates the required kernel interface; on it, commands that need per-domain support fail with exit code <code>38</code> and the message <span class="notranslate"><code>Domain limits are not supported by this kernel</code></span>.</p><p>In addition to the <a href="#prerequisites">CloudLinux Isolates prerequisites</a>, per-domain LVE limits require:</p><table><thead><tr><th>Package</th><th>Minimum Version</th></tr></thead><tbody><tr><td>lve-stats3</td><td>5.1.0-1</td></tr><tr><td>lve-utils</td><td>6.6.40-1</td></tr></tbody></table><p>To check the installed versions:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>rpm -q lve-stats3 lve-utils
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="how-the-containers-are-arranged" tabindex="-1"><a class="header-anchor" href="#how-the-containers-are-arranged" aria-hidden="true">#</a> How the containers are arranged</h3><p>Understanding the container hierarchy explains most of what the statistics show:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>ROOT
└── LVP  (reseller, when reseller limits are in use)
    └── LVP  (the hosting account)          &lt;-- reported as &quot;the account&quot;
        ├── LVE  (the account&#39;s own processes — cron, SSH, non-isolated sites)
        ├── LVE  (site1.com)
        └── LVE  (site2.com)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>The account&#39;s container is the <strong>parent</strong> of its websites&#39;, and the kernel keeps the parent&#39;s counters as the sum of its children&#39;s. So the figure the statistics tools report for an account is the total for everything beneath it — its own processes <em>and</em> every isolated website. The account&#39;s own processes are a separate container at the same level as the websites, and are never reported on their own.</p><p>Because the websites are siblings of the account&#39;s own container rather than nested inside it, work done by an isolated website is charged to that website and to the account total, but never to the account&#39;s own processes — and the reverse holds too, so an account&#39;s cron jobs are never absorbed by one of its websites.</p><p><strong>Limits nest, even though usage does not.</strong> A domain is bounded by its account&#39;s limits, which are in turn bounded by the reseller&#39;s; raising a domain&#39;s limit above its account&#39;s does not grant it more than the account has. A domain with no explicit limits of its own is simply bounded by its account&#39;s — registering a domain does not, by itself, restrict it.</p><h3 id="enabling-per-domain-limits" tabindex="-1"><a class="header-anchor" href="#enabling-per-domain-limits" aria-hidden="true">#</a> Enabling per-domain limits</h3><p>Under a control panel, use the <a href="#command-reference"><code>cagefsctl --site-isolation-*</code> commands</a> — they enable both isolation layers together and are the supported administrator path.</p><p>The underlying <span class="notranslate"><code>lvectl</code></span> commands are available for integration scripts, and for inspecting or repairing state:</p><table><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><span class="notranslate"><code>lvectl allow-domain-limits &lt;user&gt;</code></span></td><td>Create the account&#39;s LVP and allow per-domain limits for it. Idempotent.</td></tr><tr><td><span class="notranslate"><code>lvectl deny-domain-limits &lt;user&gt;</code></span></td><td>Remove the account&#39;s LVP and disallow per-domain limits.</td></tr><tr><td><span class="notranslate"><code>lvectl enable-domain-limits &lt;domain&gt;</code></span></td><td>Register a domain LVE. The owner and document root are resolved from the control panel.</td></tr><tr><td><span class="notranslate"><code>lvectl disable-domain-limits &lt;domain&gt;</code></span></td><td>Unregister the domain LVE and remove its registry entry.</td></tr><tr><td><span class="notranslate"><code>lvectl list-domains &lt;uid&gt;</code></span></td><td>List the domain LVEs of the account with the given numeric UID.</td></tr><tr><td><span class="notranslate"><code>lvectl regenerate-domains --username &lt;user&gt; ...</code></span></td><td>Refresh the domain configuration and id mapping after a rename or document root change.</td></tr></tbody></table>`,250)),a("p",null,[e[11]||(e[11]=t("See ",-1)),s(i,{to:"/cloudlinuxos/command-line_tools/#lvectl"},{default:n(()=>e[10]||(e[10]=[t("lvectl",-1)])),_:1,__:[10]}),e[12]||(e[12]=t(" for the full syntax.",-1))]),e[45]||(e[45]=o('<div class="tip custom-block"><p class="custom-block-title">Note</p><p><span class="notranslate"><code>lvectl list-domains</code></span> lists the members of an account&#39;s LVP. For a <em>reseller</em>, that LVP holds the reseller&#39;s member accounts rather than domains, so the command&#39;s output alone does not tell you whether an account is isolated. A member account resolves in <span class="notranslate"><code>/etc/passwd</code></span>; a domain LVE id never does.</p></div><p>The domain renaming, document root changes and account renames performed through a supported control panel are handled by the panel hooks, which call <span class="notranslate"><code>lvectl regenerate-domains</code></span> automatically. Run it by hand only after changing these outside the panel.</p><h3 id="setting-per-domain-limits" tabindex="-1"><a class="header-anchor" href="#setting-per-domain-limits" aria-hidden="true">#</a> Setting per-domain limits</h3><p>Per-domain limits are set by the account owner with <a href="#per-domain-resource-limits"><code>isolatectl limits</code></a>, not by the administrator: there is no <span class="notranslate"><code>lvectl</code></span> command that sets an individual domain&#39;s limits. Administrators control the account-level limits, which bound every domain underneath them.</p><p>Where the state lives:</p><table><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><span class="notranslate"><code>~/.lve/domains.json</code></span></td><td>The account&#39;s per-domain limits and its list of isolated domains. This is the file <span class="notranslate"><code>isolatectl limits apply</code></span> reads when re-applying limits to the kernel.</td></tr><tr><td><span class="notranslate"><code>/etc/container/lvd_ids/&lt;uid&gt;</code></span></td><td>The account&#39;s domain-name-to-LVE-id registry.</td></tr></tbody></table><h3 id="viewing-per-domain-usage" tabindex="-1"><a class="header-anchor" href="#viewing-per-domain-usage" aria-hidden="true">#</a> Viewing per-domain usage</h3><p>Per-domain statistics are collected by default once the feature is active. Every statistics tool can report them:</p><table><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><a href="#per-domain-statistics"><code>isolatectl stats</code></a></td><td>For the <strong>account owner</strong> — usage for their own isolated domains.</td></tr><tr><td><span class="notranslate"><code>lveinfo --with-domains</code></span>, <span class="notranslate"><code>lveinfo --domain &lt;domain&gt;</code></span></td><td>Historical per-domain usage, with the <span class="notranslate"><code>domain_id</code></span>, <span class="notranslate"><code>domain</code></span> and <span class="notranslate"><code>parent_uid</code></span> columns added.</td></tr><tr><td><span class="notranslate"><code>cloudlinux-statistics --with-domains</code></span></td><td>A <span class="notranslate"><code>domains</code></span> array nested inside each account object.</td></tr><tr><td><span class="notranslate"><code>cloudlinux-top --domains</code></span></td><td>Current per-domain usage. Note the plural: <span class="notranslate"><code>-d</code>/<code>--domain</code></span> on this tool is an unrelated filter.</td></tr><tr><td><span class="notranslate"><code>lvechart --domain &lt;domain&gt;</code></span></td><td>A usage chart for one domain instead of the account.</td></tr></tbody></table>',9)),a("p",null,[e[14]||(e[14]=t("Each ",-1)),e[15]||(e[15]=a("span",{class:"notranslate"},[a("code",null,"--domain")],-1)),e[16]||(e[16]=t(" selector accepts a domain name, a document root, or a numeric domain LVE id. See ",-1)),s(i,{to:"/cloudlinuxos/command-line_tools/#lveinfo"},{default:n(()=>e[13]||(e[13]=[t("Command Line Tools",-1)])),_:1,__:[13]}),e[17]||(e[17]=t(" for full syntax.",-1))]),e[46]||(e[46]=o(`<div class="tip custom-block"><p class="custom-block-title">Note</p><p>On an account with no isolated domains, these options are accepted and change nothing — the output is identical to the same command without them.</p></div><h3 id="reading-per-domain-figures" tabindex="-1"><a class="header-anchor" href="#reading-per-domain-figures" aria-hidden="true">#</a> Reading per-domain figures</h3><p>Three properties of the numbers regularly surprise people reading them for the first time. None of them indicates a fault.</p><p><strong>A website&#39;s usage is part of its account&#39;s, not additional to it.</strong> The per-domain rows break the account&#39;s figure down; they do not add to it:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>account  =  the account&#39;s own work  +  site1.com  +  site2.com  + ...
            (cron, SSH, non-isolated
             sites — everything outside
             an isolated website)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div>`,5)),a("p",null,[e[19]||(e[19]=a("strong",null,"Faults are counted per container, then rolled up.",-1)),e[20]||(e[20]=t(" The kernel records a fault only against the container whose limit refused the request. ",-1)),e[21]||(e[21]=a("span",{class:"notranslate"},"lve-stats",-1)),e[22]||(e[22]=t(" then rolls a website's faults into its account's total, so an account read ",-1)),e[23]||(e[23]=a("em",null,"without",-1)),e[24]||(e[24]=t(" a per-domain option already includes its websites' faults; passing ",-1)),e[25]||(e[25]=a("span",{class:"notranslate"},[a("code",null,"--with-domains")],-1)),e[26]||(e[26]=t(" splits them apart again. The ",-1)),s(i,{to:"/cloudlinuxos/cloudlinux_os_components/#customize-lve-stats2-notifications"},{default:n(()=>e[18]||(e[18]=[t("user notification email",-1)])),_:1,__:[18]}),e[27]||(e[27]=t(" is the one place that subtracts them instead, so that the same refusal is not reported twice in a message that already lists the site.",-1))]),a("p",null,[e[29]||(e[29]=a("strong",null,"Per-domain history is kept for fewer days than per-account history",-1)),e[30]||(e[30]=t(" — 7 days against 30, by default. A report covering a longer range returns correspondingly less per-domain data than account data, without the rows themselves indicating why. Both windows are administrator-configurable; see ",-1)),e[31]||(e[31]=a("span",{class:"notranslate"},[a("code",null,"keep_history_days_domain")],-1)),e[32]||(e[32]=t(" in ",-1)),s(i,{to:"/cloudlinuxos/cloudlinux_os_components/#configuration"},{default:n(()=>e[28]||(e[28]=[t("LVE-Stats 2 configuration",-1)])),_:1,__:[28]}),e[33]||(e[33]=t(" (",-1)),e[34]||(e[34]=a("span",{class:"notranslate"},[a("code",null,"/etc/sysconfig/lvestats2")],-1)),e[35]||(e[35]=t(").",-1))]),e[47]||(e[47]=a("h3",{id:"fault-notifications",tabindex:"-1"},[a("a",{class:"header-anchor",href:"#fault-notifications","aria-hidden":"true"},"#"),t(" Fault notifications")],-1)),e[48]||(e[48]=a("p",null,"When a website hits one of its own limits, the notification sent to the account owner names the website that faulted, alongside the limit it hit. Notifications continue to be addressed per account, and the thresholds and period that govern the account-level notification govern the per-domain section too — so enabling per-domain limits does not, by itself, change who is emailed or how often.",-1)),a("p",null,[e[37]||(e[37]=t("Administrators customising the email templates should see the ",-1)),e[38]||(e[38]=a("span",{class:"notranslate"},[a("code",null,"domain_faults")],-1)),e[39]||(e[39]=t(" variable in ",-1)),s(i,{to:"/cloudlinuxos/cloudlinux_os_components/#customize-lve-stats2-notifications"},{default:n(()=>e[36]||(e[36]=[t("Customize LVE-stats2 notifications",-1)])),_:1,__:[36]}),e[40]||(e[40]=t(".",-1))]),e[49]||(e[49]=o(`<h3 id="troubleshooting-per-domain-limits" tabindex="-1"><a class="header-anchor" href="#troubleshooting-per-domain-limits" aria-hidden="true">#</a> Troubleshooting per-domain limits</h3><p><strong>&quot;Domain limits are not supported by this kernel (requires lve_lvp_create2)&quot;</strong></p><p>The kernel predates per-domain LVE support. Per-domain limits require CloudLinux OS 8 or 9; on CloudLinux OS 7 the <a href="#cagefs-per-domain">CageFS half</a> of CloudLinux Isolates is still available.</p><p><strong>Isolation was enabled, but no domain LVEs were created</strong></p><p>The <span class="notranslate"><code>cagefsctl --site-isolation-*</code></span> commands always apply the filesystem layer, and add the per-domain LVE only when the <a href="#per-domain-prerequisites">prerequisites</a> are met. Check the installed versions:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>rpm -q lve-stats3 lve-utils
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>If either is below the minimum, update it and then re-run <span class="notranslate"><code>cagefsctl --site-isolation-enable &lt;domain&gt;</code></span>. Removing isolation is never gated this way, so any containers created by an earlier version can always be torn down.</p><p><strong>&quot;No domain limits configured for UID <em>N</em>&quot;</strong></p><p>The account exists but has no isolated domains. Enable isolation for a domain first — <span class="notranslate"><code>cagefsctl --site-isolation-enable &lt;domain&gt;</code></span>. A genuinely unknown account reports <span class="notranslate"><code>UID N does not exist</code></span> instead.</p><p><strong>A domain&#39;s statistics stopped after a rename or a document root change</strong></p><p>The domain&#39;s registry entry is keyed on its document root. Changes made through a supported control panel are handled by the panel hooks; if the change was made outside the panel, refresh the mapping by hand:</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>lvectl regenerate-domains --username &lt;user&gt; --domain &lt;new&gt; --old-domain &lt;old&gt;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><hr>`,13))])}const v=d(c,[["render",p],["__file","index.html.vue"]]);export{v as default};
